extensibilityCode.react:
// Modo múltiplo: cada escolhido vira um chip dentro do campo
<Combobox
  multiple
  items={tecnologias}
  value={escolhidas}
  onValueChange={setEscolhidas}
>
  <ComboboxLabel>Tecnologias</ComboboxLabel>
  <ComboboxInputWrapper>
    <ComboboxChips>
      {escolhidas.map((item) => (
        <ComboboxChip key={item.value} value={item.value}>
          {item.label}
          <ComboboxChipRemove aria-label={`Remover ${item.label}`} />
        </ComboboxChip>
      ))}
    </ComboboxChips>
    <ComboboxInput placeholder="Adicionar tecnologia" />
    <ComboboxTrigger aria-label="Abrir lista">
      <ComboboxIcon />
    </ComboboxTrigger>
  </ComboboxInputWrapper>
</Combobox>

extensibilityCode.vanilla:
// Modo múltiplo: cada escolhido vira um chip dentro do campo
const campo = createCombobox({
  id: 'tecnologias',
  label: 'Tecnologias',
  placeholder: 'Adicionar tecnologia',
  multiple: true,
  defaultValue: ['react', 'vue'],
  items: [
    { value: 'react', label: 'React' },
    { value: 'vue', label: 'Vue' },
    { value: 'svelte', label: 'Svelte' },
    { value: 'angular', label: 'Angular' },
  ],
  // Nome próprio por chip — "Remover" sozinho não diz qual
  removeLabel: (item) => `Remover ${item.label}`,
});

customizationCode.web:
/* Lista mais larga e mais alta que o padrão */
.nds-combobox-popup {
  min-width: 16rem;
}

.nds-combobox-list {
  max-height: 24rem;
}

/* Campo mais alto sem cravar altura — o crescimento vem do padding */
.nds-combobox-input-wrapper {
  padding-block: var(--spacing-2-5);
}

/* Chip arredondado por completo */
.nds-combobox-chip {
  border-radius: var(--radius-full);
}

